import{_ as a,o as r,c as i,a2 as t}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"使用指南","description":"按从启动服务到阅读结果的顺序，完成一次可验证的 Ershu 使用流程。","frontmatter":{"page_id":"guide-index","description":"按从启动服务到阅读结果的顺序，完成一次可验证的 Ershu 使用流程。"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786289447000}'),o={name:"guide/index.md"};function l(d,e,n,p,s,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to &quot;使用指南&quot;">​</a></h1><p>这组指南帮助你从一个尚未配置的 Ershu 环境出发，创建项目、完成第一次分析，再用文档、搜索和项目问答理解代码。每一步都写明了成功后应看到什么。</p><h2 id="建议阅读顺序" tabindex="-1">建议阅读顺序 <a class="header-anchor" href="#建议阅读顺序" aria-label="Permalink to &quot;建议阅读顺序&quot;">​</a></h2><ol><li><p><a href="./quick-start">把 Ershu 启动到可登录状态</a></p><p>准备基础设施、API、Worker 和前端。完成后，浏览器会显示首次管理员设置页或登录页。</p></li><li><p><a href="./create-first-project">创建第一个项目</a></p><p>创建首位管理员、配置模型通道，并接入第一个仓库。完成后，项目概览会显示你刚创建的项目和仓库。</p></li><li><p><a href="./follow-a-run">开始并跟踪第一次分析</a></p><p>第一次运行必须选择完整项目，并覆盖全部活动仓库。完成后，运行状态会变为“已完成”或“已完成但有警告”。</p></li><li><p><a href="./read-search-chat">阅读文档、搜索项目和继续提问</a></p><p>从生成的文档进入源码引用，按关键词或语义搜索项目，并在 Docs 页面发起项目范围的问答。</p></li></ol><h2 id="先了解三个边界" tabindex="-1">先了解三个边界 <a class="header-anchor" href="#先了解三个边界" aria-label="Permalink to &quot;先了解三个边界&quot;">​</a></h2><ul><li>当前公开安装包还没有准备好。后端仍通过私有开发源取得 Core 和其他组件，没有相应权限时无法完成 <code>uv sync</code>。</li><li>创建项目不会自动开始分析。你需要进入项目的 Runs 页面创建运行。</li><li>API 只负责接收运行请求。Worker 没有运行时，任务会留在队列中，不会生成文档和索引。</li></ul><p>如果你在启动或使用过程中遇到问题，请从<a href="./../development/troubleshooting">开发故障排查</a>中的症状表开始检查。</p>',7)])])}const _=a(o,[["render",l]]);export{u as __pageData,_ as default};
